### Create the Processor

First, you will need to create a new processor, `LatencyProcessor` that will record processing latencies.

#### 1. Create `latency_processor.go`

This file will contain the implementation of the latency processor.

```go
// cmd/mdatagen/internal/latency_processor.go
package internal

import (
    "context"
    "time"

    "go.opentelemetry.io/collector/component"
    "go.opentelemetry.io/collector/consumer"
    "go.opentelemetry.io/collector/pipeline"
    "go.opentelemetry.io/collector/processor"
    "go.opentelemetry.io/collector/metadata"
)

type LatencyProcessor struct {
    nextConsumer consumer.Traces
}

func NewLatencyProcessor(nextConsumer consumer.Traces) *LatencyProcessor {
    return &LatencyProcessor{nextConsumer: nextConsumer}
}

func (lp *LatencyProcessor) ProcessTraces(ctx context.Context, traces pdata.Traces) error {
    start := time.Now()

    // Pass the traces to the next consumer
    err := lp.nextConsumer.ConsumeTraces(ctx, traces)

    latency := time.Since(start)
    RecordProcessingLatency(latency) // Custom metric recording of the latency

    return err
}

